import os
import hashlib
import shutil
import logging
from datetime import datetime

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def calculate_sha256(filepath):
    """Calculates the SHA-256 checksum of a file."""
    hasher = hashlib.sha256()
    try:
        with open(filepath, 'rb') as file:
            while True:
                chunk = file.read(4096)
                if not chunk:
                    break
                hasher.update(chunk)
        return hasher.hexdigest()
    except FileNotFoundError:
        logging.error(f"File not found: {filepath}")
        return None
    except PermissionError:
        logging.error(f"Permission error reading: {filepath}")
        return None

def backup_website(source_dir, backup_dir, file_types):
    """Backs up a website to a local directory with integrity checks and rollback."""

    if not os.path.exists(backup_dir):
        os.makedirs(backup_dir)

    for root, _, files in os.walk(source_dir):
        for file in files:
            if any(file.endswith(ext) for ext in file_types):
                filepath = os.path.join(root, file)
                relpath = os.path.relpath(filepath, source_dir)
                backup_path = os.path.join(backup_dir, relpath)
                os.makedirs(os.path.dirname(backup_path), exist_ok=True)

                try:
                    shutil.copy2(filepath, backup_path)  # copy2 preserves metadata
                    checksum = calculate_sha256(filepath)
                    if checksum:
                        with open(os.path.join(backup_path, ".sha256"), "w") as f:
                            f.write(checksum)
                        logging.info(f"Backed up {filepath} to {backup_path} with SHA256: {checksum}")
                    else:
                        logging.warning(f"Failed to calculate SHA256 for {filepath}")

                except FileNotFoundError:
                    logging.error(f"File not found during backup: {filepath}")
                except PermissionError:
                    logging.error(f"Permission error during backup: {filepath}")
                except Exception as e:
                    logging.error(f"An unexpected error occurred during backup of {filepath}: {e}")

def rollback_website(source_dir, backup_dir, file_types):
    """Rolls back the website to the latest backup."""

    if not os.path.exists(backup_dir):
        logging.warning(f"Backup directory not found: {backup_dir}")
        return

    # Get the latest backup directory
    backup_dirs = [d for d in os.listdir(backup_dir) if os.path.isdir(os.path.join(backup_dir, d))]
    if not backup_dirs:
        logging.warning(f"No backup directories found in {backup_dir}")
        return

    latest_backup_dir = max(backup_dirs, key=lambda d: datetime.strptime(d, '%Y%m%d'))
    latest_backup_path = os.path.join(backup_dir, latest_backup_dir)

    for root, _, files in os.walk(source_dir):
        for file in files:
            if any(file.endswith(ext) for ext in file_types):
                filepath = os.path.join(root, file)
                relpath = os.path.relpath(filepath, source_dir)
                backup_path = os.path.join(latest_backup_path, relpath)

                try:
                    if os.path.exists(backup_path):
                        checksum_file = os.path.join(backup_path, ".sha256")
                        if os.path.exists(checksum_file):
                            with open(checksum_file, "r") as f:
                                expected_checksum = f.read().strip()
                            calculated_checksum = calculate_sha256(filepath)
                            if calculated_checksum == expected_checksum:
                                shutil.copy2(backup_path, filepath)
                                logging.info(f"Rolled back {filepath} from {latest_backup_dir}")
                            else:
                                logging.warning(f"Checksum mismatch for {filepath}.  Skipping rollback.")
                        else:
                            shutil.copy2(backup_path, filepath)
                            logging.info(f"Rolled back {filepath} from {latest_backup_dir} (no checksum)")
                    else:
                        logging.warning(f"Backup file not found: {backup_path}")

                except FileNotFoundError:
                    logging.error(f"Backup file not found during rollback: {backup_path}")
                except PermissionError:
                    logging.error(f"Permission error during rollback: {backup_path}")
                except Exception as e:
                    logging.error(f"An unexpected error occurred during rollback of {filepath}: {e}")

if __name__ == "__main__":
    source_directory = "/var/www/html"
    backup_directory = "/local/backup/site_v1"
    file_types = [".html", ".css", ".js"]

    backup_website(source_directory, backup_directory, file_types)
    rollback_website(source_directory, backup_directory, file_types)
