class UserDataService {
  constructor(apiEndpoint, rateLimit, timeout) {
    this.apiEndpoint = apiEndpoint;
    this.rateLimit = rateLimit;
    this.timeout = timeout;
    this.retryCount = 0;
    this.maxRetries = 3;
  }

  isValidUserId(userId) {
    return typeof userId === 'number' && userId > 0;
  }

  async getUserData(userId) {
    if (!this.isValidUserId(userId)) {
      throw new Error("Invalid user ID. Must be a positive number.");
    }

    const url = this.apiEndpoint.replace('{id}', userId);

    return await this.fetchData(url);
  }

  async fetchData(url) {
    try {
      const response = await fetch(url, {
        timeout: this.timeout,
        mode: 'cors', // Explicitly set CORS mode
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      const data = await response.json();
      return data;
    } catch (error) {
      this.retry(url);
      throw error;
    }
  }

  retry(url) {
    if (this.retryCount >= this.maxRetries) {
      throw new Error(`Max retries (${this.maxRetries}) reached for ${url}`);
    }

    this.retryCount++;

    setTimeout(() => {
      this.fetchData(url);
    }, this.exponentialBackoff(this.retryCount));
  }

  exponentialBackoff(attempt) {
    const base = 1000; // milliseconds
    const factor = 2;
    return base * Math.pow(factor, attempt);
  }
}

