/**
 * Fetches user data from a REST API endpoint.
 *
 * @param {string} id The user ID.
 * @returns {Promise<object>} A promise that resolves with the user data or rejects with an error.
 * @throws {Error} If the input ID is invalid.
 */
async function fetchUser(id) {
  const apiEndpoint = "https://api.example.com/users/" + id;

  // Input validation
  if (typeof id !== 'string') {
    return Promise.reject(new Error("Invalid input: ID must be a string."));
  }

  if (!/^[a-zA-Z0-9]+$/.test(id)) {
    return Promise.reject(new Error("Invalid input: ID must be alphanumeric."));
  }

  try {
    const response = await fetch(apiEndpoint);

    if (!response.ok) {
      if (response.status === 404) {
        return Promise.reject(new Error(`User not found: ${response.status}`));
      } else if (response.status >= 500) {
        return Promise.reject(new Error(`Server error: ${response.status}`));
      } else {
        return Promise.reject(new Error(`HTTP error: ${response.status}`));
      }
    }

    const data = await response.json();

    if (typeof data.id !== 'string' || typeof data.name !== 'string' || typeof data.email !== 'string') {
      return Promise.reject(new Error("Invalid JSON response format."));
    }

    return data;

  } catch (error) {
    return Promise.reject(new Error(`Network error: ${error.message}`));
  }
}
