      .map(
        (key) =>
          `${key}: ${data[key] !== undefined ? data[key] : ''}`
      )
      .join(", ");
    console.log(`[${new Date().toISOString()}] ${formattedData}`);
  };

  const getPerformanceMetrics = () => {
    return new Promise((resolve, reject) => {
      const metrics = {};

      // Load Time
      const loadTimePromise = new Promise((resolveLoadTime) => {
        const startTime = performance.now();
        performance.getTiming({
          onTimings: (timing) => {
            metrics.loadTime = timing.loadEventStart - timing.fetchStart;
            resolveLoadTime();
          },
        });
      });

      // First Contentful Paint
      const fcpPromise = new Promise((resolveFCP) => {
        performance.getFCP((fcp) => {
          metrics.FCP = fcp;
          resolveFCP();
        });
      });

      // Largest Contentful Paint
      const lcpPromise = new Promise((resolveLCP) => {
        performance.getLCP((lcp) => {
          metrics.LCP = lcp;
          resolveLCP();
        });
      });

      Promise.all([loadTimePromise, fcpPromise, lcpPromise])
        .then((results) => {
          resolve(metrics);
        })
        .catch((error) => {
          reject(error);
        });
    });
  };

  const validateInput = (data) => {
    if (!Array.isArray(data) || data.length === 0) {
      throw new Error("Metrics to monitor must be a non-empty array.");
    }
    for (const metric of data) {
      if (!metricsToMonitor.includes(metric)) {
        throw new Error(
          `Invalid metric: ${metric}. Supported metrics are: ${metricsToMonitor.join(
            ", "
          )}`
        );
      }
    }
  };

  return {
    startMonitoring: async (metrics) => {
      try {
        await validateInput(metrics);
        const metricsData = await getPerformanceMetrics(metrics);
        log(metricsData);
      } catch (error) {
        console.error("Error monitoring performance:", error);
      }
    },
  };
})();

